class CustomerCache:
    def __init__(self):
        self.values = {}

    def put(self, tenant, item, value):
        self.values[(tenant, item)] = value

    def get(self, tenant, item):
        return self.values.get((tenant, item))

    def invalidate(self, tenant):
        for key in [k for k in self.values if k[0] == tenant]:
            del self.values[key]

